{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    # The three vertical cells are painted according to the level of the
    # gray mark in each 3-column panel.
    out=[[0]*w for _ in range(h)]
    for b in range(w//3):
        vals=[]
        for r in range(h):
            if any(grid[r][3*b:3*b+3]): vals.append(r)
        if not vals: continue
        if vals==[0]: col=6
        elif vals==[1]: col=4
        elif vals==[2]: col=1
        else:
            # a composite/diagonal mark is treated as the central mark
            col=4
        for r in range(h):
            for c in range(3*b,min(3*b+3,w)): out[r][c]=col
    return out"}

